def f(q: int, queries: List[Tuple[int,...]]) -> int:
    '''
    q: an integer
    queries: a list of tuples, where each tuple represents a query
    '''
    MOD = 10**9 + 7
    prefix = [0]*(q+1)
    for i in range(1, q+1):
        prefix[i] = (prefix[i-1] + i) % MOD
    res = 0
    for query in queries:
        if query[0] == 0:
            res = (res + query[1]) % MOD
        elif query[0] == 1:
            res = (res - query[1]) % MOD
        elif query[0] == 2:
            res = (res + query[1]*(query[1]+1)//2) % MOD
        elif query[0] == 3:
            res = (res + prefix[query[1]] - prefix[query[2]-1]) % MOD
    return res
